#pragma once

#include <cstddef>

/**
 * ICAO type designator -> display name ("B38M" -> "Boeing 737 MAX 8"),
 * sorted by code for binary search. Generated by
 * scripts/build_aircraft_types.py -- edit the list there.
 */
namespace data::aircraft_types {

struct AircraftType {
  char code[5];
  const char* name;
};

constexpr size_t kTypeCount = 214;
constexpr size_t kMaxNameLen = 20;
extern const AircraftType kTypes[kTypeCount];

/** Display name for an ICAO type designator, or nullptr if unknown. */
const char* nameFor(const char* code);

}  // namespace data::aircraft_types
